import { useEffect, useMemo, useRef, useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import { Printer, Search, Plus, CheckCircle2, AlertTriangle, FileText, FileSpreadsheet, ChevronDown } from 'lucide-react';
import { canWriteFinance } from '../services/financeService';
import type { Payable, PaymentTransaction, Receivable, SaleRecord, PurchaseRecord, Expense, CashClosure, ErpSettings, Product, InventoryMovement, CashMovement, Customer, Supplier, MissingProductRequest } from '../domain/types';

const money=(n:number)=>new Intl.NumberFormat('es-HN',{style:'currency',currency:'HNL'}).format(n);
const day=(s:string)=>{if(!s)return '—';const d=new Date(s.length===10?s+'T12:00:00':s);return Number.isNaN(d.getTime())?s:d.toLocaleDateString('es-HN');};
const overdue=(due:string,balance:number)=>balance>0&&!!due&&due<new Date().toISOString().slice(0,10);
const balanceOf=(x:{total:number;paid:number;creditNotes?:number;debitNotes?:number})=>Math.max(0,x.total+(x.debitNotes||0)-x.paid-(x.creditNotes||0));
const validAmount=(v:number,b:number)=>Number.isFinite(v)&&v>0&&v<=b;
const escapeHtml=(value:unknown)=>String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');

export function ReceivablesModule({receivables,setReceivables,transactions,setTransactions,remoteReady,syncStatus}:{receivables:Receivable[];setReceivables:Dispatch<SetStateAction<Receivable[]>>;transactions:PaymentTransaction[];setTransactions:Dispatch<SetStateAction<PaymentTransaction[]>>;remoteReady:boolean;syncStatus:'loading'|'saving'|'synced'|'error'}) {
  const canWrite=canWriteFinance(remoteReady,syncStatus);
  const [search,setSearch]=useState(''); const [status,setStatus]=useState('pendiente'); const [amounts,setAmounts]=useState<Record<number,string>>({}); const [methods,setMethods]=useState<Record<number,'Efectivo'|'Transferencia'>>({}); const [references,setReferences]=useState<Record<number,string>>({}); const [notice,setNotice]=useState(''); const [lastReceiptId,setLastReceiptId]=useState<number|null>(null); const [historyOpen,setHistoryOpen]=useState(false); const processing=useRef<Set<number>>(new Set()); useEffect(()=>{processing.current.clear();},[receivables,transactions]);
  const normalizeSearch=(value:string)=>value.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLocaleLowerCase().trim();
  const filtered=useMemo(()=>receivables.filter(r=>{const b=balanceOf(r),late=overdue(r.dueDate,b),paid=b===0,partial=r.paid>0&&b>0;const s=status==='todos'||(status==='pendiente'&&b>0)||(status==='vencida'&&late)||(status==='pagada'&&paid);const stateTerms=paid?'pagada pagado completada':late?'vencida vencido atrasada':partial?'parcial parcialmente abonada pendiente':'pendiente';const dateTerms=[r.date,r.dueDate,day(r.date),day(r.dueDate)].join(' ');const searchable=normalizeSearch(`${r.customer} ${r.saleId} ${dateTerms} ${stateTerms}`);return s&&searchable.includes(normalizeSearch(search));}),[receivables,search,status]);
  const pending=receivables.reduce((s,r)=>s+balanceOf(r),0),lateTotal=receivables.reduce((s,r)=>s+(overdue(r.dueDate,balanceOf(r))?balanceOf(r):0),0);
  const paymentHistory=transactions.filter(t=>t.type==='Cobro');
  const openPrintDocument=(title:string,content:string)=>{
    const printWindow=window.open('','_blank','width=900,height=720');
    if(!printWindow){setNotice('El navegador bloqueó la ventana de impresión. Permite las ventanas emergentes para imprimir.');return;}
    printWindow.onload=()=>{printWindow.focus();printWindow.print();};
    printWindow.document.open();
    printWindow.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title><style>
      *{box-sizing:border-box}body{margin:0;padding:32px;font-family:Arial,sans-serif;color:#21352e;background:#fff;font-size:12px;line-height:1.45}.document{max-width:820px;margin:0 auto}.brand{display:flex;align-items:center;gap:14px;padding-bottom:18px;border-bottom:2px solid #167b61}.brand-mark{width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:#e8f3ee;color:#167b61;font-weight:800;font-size:26px}.brand h1{margin:0;color:#167b61;font-size:22px;letter-spacing:.04em}.brand p{margin:3px 0 0;color:#6b8077}.doc-title{margin:22px 0 14px;font-size:19px;color:#193c30}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px 22px;margin:18px 0}.meta div{padding:8px 0;border-bottom:1px solid #e7eeea}.meta span{display:block;color:#70837a;font-size:10px;text-transform:uppercase;letter-spacing:.05em}.meta strong{display:block;margin-top:3px;font-size:12px}.amount-panel{margin:18px 0;padding:16px;border:1px solid #d7e6dd;border-radius:10px;background:#f4f9f6}.amount-panel span{display:block;color:#61776c;font-size:11px}.amount-panel strong{display:block;margin-top:4px;color:#12664d;font-size:25px}.totals{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.total-card{padding:12px;border:1px solid #e0e9e4;border-radius:9px}.total-card span{display:block;color:#71847b;font-size:10px}.total-card strong{display:block;margin-top:6px;font-size:15px}.doc-table{width:100%;border-collapse:collapse;margin-top:12px}.doc-table th{padding:9px 8px;background:#edf4f0;color:#476257;text-align:left;font-size:10px;text-transform:uppercase}.doc-table td{padding:9px 8px;border-bottom:1px solid #e7eeea;vertical-align:top}.num{text-align:right!important;white-space:nowrap}.grand-total td{font-weight:800;border-top:2px solid #bbcec3}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:50px;margin-top:54px}.signature{padding-top:8px;border-top:1px solid #8a9b92;text-align:center;color:#61756b;font-size:10px}.foot{margin-top:25px;padding-top:12px;border-top:1px solid #e4ebe7;color:#83928a;font-size:10px;text-align:center}.notice{margin-top:20px;color:#687d73;font-size:10px}@page{size:auto;margin:12mm}@media print{body{padding:0}.document{max-width:none}.no-print{display:none!important}}@media(max-width:560px){body{padding:16px}.meta,.totals{grid-template-columns:1fr 1fr}.doc-table{font-size:10px}.doc-table th,.doc-table td{padding:6px 4px}}
    </style></head><body>${content}</body></html>`);
    printWindow.document.close();
  };
  const printReceipt=(payment:PaymentTransaction)=>{
    const account=receivables.find(r=>r.id===payment.accountId);
    const related=transactions.filter(t=>t.type==='Cobro'&&t.accountId===payment.accountId).sort((a,b)=>a.date.localeCompare(b.date)||a.id-b.id);
    const paidThrough=related.filter(t=>t.date<payment.date||(t.date===payment.date&&t.id<=payment.id)).reduce((sum,t)=>sum+t.amount,0);
    const balanceAfter=payment.balanceAfter??Math.max(0,(account?.total??payment.amount)-paidThrough);
    const balanceBefore=payment.balanceBefore??balanceAfter+payment.amount;
    const dateLabel=new Date(payment.date).toLocaleString('es-HN');
    const body=`<main class="document"><header class="brand"><div class="brand-mark">D</div><div><h1>DIFARMÁS</h1><p>Comprobante de pago de cuenta por cobrar</p></div></header><h2 class="doc-title">RECIBO DE ABONO</h2><div class="meta"><div><span>N.º de recibo</span><strong>RC-${escapeHtml(payment.id)}</strong></div><div><span>Fecha y hora</span><strong>${escapeHtml(dateLabel)}</strong></div><div><span>Recibido de</span><strong>${escapeHtml(payment.party)}</strong></div><div><span>Venta / factura</span><strong>${account?'#'+escapeHtml(account.saleId):'Cuenta #'+escapeHtml(payment.accountId)}</strong></div><div><span>Forma de pago</span><strong>${escapeHtml(payment.paymentMethod||'No especificado')}</strong></div><div><span>Referencia</span><strong>${escapeHtml(payment.reference||'—')}</strong></div></div><section class="amount-panel"><span>Importe recibido</span><strong>${escapeHtml(money(payment.amount))}</strong></section><div class="meta"><div><span>Saldo antes del abono</span><strong>${escapeHtml(money(balanceBefore))}</strong></div><div><span>Saldo después del abono</span><strong>${escapeHtml(money(balanceAfter))}</strong></div></div><p class="notice">Este recibo confirma la recepción del abono indicado y su aplicación a la cuenta por cobrar señalada.</p><div class="signatures"><div class="signature">Firma de quien recibe</div><div class="signature">Firma del cliente</div></div><footer class="foot">DIFARMÁS · Documento de control interno y comprobante para el cliente</footer></main>`;
    openPrintDocument('Recibo RC-'+payment.id,body);
  };
  const printReceivableNote=(note:PaymentTransaction)=>{
    const account=receivables.find(r=>r.id===note.accountId);
    const isCredit=note.type==='Nota de crédito';
    const prefix=isCredit?'NC':'ND';
    const number=note.reference?.trim()||prefix+'-'+note.id;
    const dateLabel=new Date(note.date).toLocaleString('es-HN');
    const balanceBefore=note.balanceBefore??0;
    const balanceAfter=note.balanceAfter??(isCredit?Math.max(0,balanceBefore-note.amount):balanceBefore+note.amount);
    const body=`<main class="document"><header class="brand"><div class="brand-mark">D</div><div><h1>DIFARMÁS</h1><p>Documento de ajuste de cuenta por cobrar</p></div></header><h2 class="doc-title">${isCredit?'NOTA DE CRÉDITO':'NOTA DE DÉBITO'}</h2><div class="meta"><div><span>N.º de documento</span><strong>${escapeHtml(number)}</strong></div><div><span>Fecha y hora</span><strong>${escapeHtml(dateLabel)}</strong></div><div><span>Cliente</span><strong>${escapeHtml(note.party)}</strong></div><div><span>Factura relacionada</span><strong>${account?'#'+escapeHtml(account.saleId):'Cuenta #'+escapeHtml(note.accountId)}</strong></div><div><span>Tipo de documento</span><strong>${isCredit?'Crédito':'Débito'}</strong></div><div><span>Referencia / concepto</span><strong>${escapeHtml(note.reference||'Ajuste de cuenta por cobrar')}</strong></div></div><section class="amount-panel"><span>Importe de la ${isCredit?'nota de crédito':'nota de débito'}</span><strong>${escapeHtml(money(note.amount))}</strong></section><div class="meta"><div><span>Saldo antes del documento</span><strong>${escapeHtml(money(balanceBefore))}</strong></div><div><span>Saldo después del documento</span><strong>${escapeHtml(money(balanceAfter))}</strong></div></div><p class="notice">Este documento deja constancia de la aplicación de una ${isCredit?'nota de crédito que disminuye':'nota de débito que incrementa'} el saldo de la cuenta por cobrar indicada. No representa recepción ni entrega de efectivo.</p><div class="signatures"><div class="signature">Firma y sello de DIFARMÁS</div><div class="signature">Firma de conformidad del cliente</div></div><footer class="foot">DIFARMÁS · Comprobante de ajuste para el cliente</footer></main>`;
    openPrintDocument((isCredit?'Nota de crédito ':'Nota de débito ')+number,body);
  };
  const printCustomerStatement=(customerName:string)=>{
    const key=normalizeSearch(customerName);
    const accounts=receivables.filter(r=>normalizeSearch(r.customer)===key).sort((a,b)=>a.date.localeCompare(b.date)||a.saleId-b.saleId);
    if(!accounts.length){setNotice('No hay cuentas registradas para este cliente.');return;}
    const accountIds=new Set(accounts.map(r=>r.id));
    const customerTransactions=transactions.filter(t=>(t.type==='Cobro'||t.type==='Nota de crédito'||t.type==='Nota de débito')&&accountIds.has(t.accountId));
    const movements:{date:string;sort:number;id:number;reference:string;description:string;debit:number;credit:number}[]=[];
    accounts.forEach(account=>{
      movements.push({date:account.date,sort:0,id:account.id,reference:'Venta #'+account.saleId,description:'Venta a crédito · Vence '+day(account.dueDate),debit:account.total,credit:0});
      const paymentsForAccount=customerTransactions.filter(t=>t.accountId===account.id);
      paymentsForAccount.forEach(m=>movements.push({date:m.date,sort:1,id:m.id,reference:m.reference||((m.type==='Cobro'?'RC-':'NC-')+m.id),description:m.type==='Cobro'?'Abono a venta #'+account.saleId+' · '+(m.paymentMethod||'Pago')+(m.reference?' · Ref. '+m.reference:''):m.type+' aplicada a venta #'+account.saleId,debit:m.type==='Nota de débito'?m.amount:0,credit:m.type==='Cobro'||m.type==='Nota de crédito'?m.amount:0}));
      const paymentsForAccountCash=paymentsForAccount.filter(p=>p.type==='Cobro');
      const recorded=paymentsForAccountCash.reduce((sum,p)=>sum+p.amount,0);
      const untracked=Math.max(0,account.paid-recorded);
      if(untracked>0)movements.push({date:account.lastPaymentDate||account.date,sort:1,id:account.id,reference:'—',description:'Abonos anteriores registrados',debit:0,credit:untracked});
    });
    movements.sort((a,b)=>a.date.localeCompare(b.date)||a.sort-b.sort||a.id-b.id);
    let running=0;
    const bodyRows=movements.map(m=>{running+=m.debit-m.credit;return `<tr><td>${escapeHtml(day(m.date))}</td><td>${escapeHtml(m.reference)}</td><td>${escapeHtml(m.description)}</td><td class="num">${m.debit?escapeHtml(money(m.debit)):'—'}</td><td class="num">${m.credit?escapeHtml(money(m.credit)):'—'}</td><td class="num">${escapeHtml(money(running))}</td></tr>`;}).join('');
    const totalSales=accounts.reduce((sum,r)=>sum+r.total,0),totalPaid=accounts.reduce((sum,r)=>sum+r.paid,0),currentBalance=accounts.reduce((sum,r)=>sum+balanceOf(r),0);
    const body=`<main class="document"><header class="brand"><div class="brand-mark">D</div><div><h1>DIFARMÁS</h1><p>Estado de cuenta del cliente</p></div></header><h2 class="doc-title">ESTADO DE CUENTA</h2><div class="meta"><div><span>Cliente</span><strong>${escapeHtml(customerName)}</strong></div><div><span>Fecha de emisión</span><strong>${escapeHtml(new Date().toLocaleDateString('es-HN'))}</strong></div><div><span>Cuentas incluidas</span><strong>${accounts.length}</strong></div><div><span>Moneda</span><strong>Lempiras (HNL)</strong></div></div><section class="totals"><div class="total-card"><span>Total de ventas a crédito</span><strong>${escapeHtml(money(totalSales))}</strong></div><div class="total-card"><span>Total abonado</span><strong>${escapeHtml(money(totalPaid))}</strong></div><div class="total-card"><span>Saldo pendiente</span><strong>${escapeHtml(money(currentBalance))}</strong></div></section><h3>Detalle de movimientos</h3><table class="doc-table"><thead><tr><th>Fecha</th><th>Documento</th><th>Descripción</th><th class="num">Cargo</th><th class="num">Abono</th><th class="num">Saldo</th></tr></thead><tbody>${bodyRows||'<tr><td colspan="6">Sin movimientos registrados.</td></tr>'}<tr class="grand-total"><td colspan="3">Totales</td><td class="num">${escapeHtml(money(totalSales))}</td><td class="num">${escapeHtml(money(totalPaid))}</td><td class="num">${escapeHtml(money(currentBalance))}</td></tr></tbody></table><p class="notice">Este estado de cuenta reúne todas las ventas a crédito y abonos registrados para el cliente a la fecha de emisión.</p><footer class="foot">DIFARMÁS · Estado de cuenta generado el ${escapeHtml(new Date().toLocaleString('es-HN'))}</footer></main>`;
    openPrintDocument('Estado de cuenta - '+customerName,body);
  };

  const [selectedCustomer,setSelectedCustomer]=useState('');
  const [paymentModalOpen,setPaymentModalOpen]=useState(false);
  const [selectedInvoiceId,setSelectedInvoiceId]=useState<number|null>(null);
  const [newPaymentAmount,setNewPaymentAmount]=useState('');
  const [newPaymentMethod,setNewPaymentMethod]=useState<'Efectivo'|'Transferencia'>('Efectivo');
  const [newMovementType,setNewMovementType]=useState<'Cobro'|'Nota de crédito'|'Nota de débito'>('Cobro');
  const [newPaymentReference,setNewPaymentReference]=useState('');
  const customerNames=useMemo(()=>[...new Set(receivables.map(r=>r.customer.trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es')),[receivables]);
  const customerMatches=useMemo(()=>customerNames.filter(name=>normalizeSearch(name).includes(normalizeSearch(search))),[customerNames,search]);
  const customerAccounts=useMemo(()=>selectedCustomer?receivables.filter(r=>normalizeSearch(r.customer)===normalizeSearch(selectedCustomer)).sort((a,b)=>a.date.localeCompare(b.date)||a.saleId-b.saleId):[],[receivables,selectedCustomer]);
  const customerAccountIds=new Set(customerAccounts.map(r=>r.id));
  const customerPayments=transactions.filter(t=>t.type==='Cobro'&&customerAccountIds.has(t.accountId));
  const customerAccountMovements=transactions.filter(t=>(t.type==='Cobro'||t.type==='Nota de crédito'||t.type==='Nota de débito')&&customerAccountIds.has(t.accountId));
  const customerMovements=[...customerAccounts.map(r=>({key:'sale-'+r.id,date:r.date,kind:'Factura',reference:'Venta #'+r.saleId,description:'Venta a crédito · Vence '+day(r.dueDate),debit:r.total,credit:0,accountId:r.id})),...customerAccountMovements.map(t=>({key:'movement-'+t.id,date:t.date,kind:t.type==='Cobro'?'Abono':t.type,reference:t.reference||((t.type==='Cobro'?'RC-':'NC-')+t.id),description:t.type==='Cobro'?(t.paymentMethod||'Pago')+(t.reference?' · Ref. '+t.reference:''):t.type,debit:t.type==='Nota de débito'?t.amount:0,credit:t.type==='Cobro'||t.type==='Nota de crédito'?t.amount:0,accountId:t.accountId}))].sort((a,b)=>a.date.localeCompare(b.date)||(a.kind==='Factura'?-1:1));
  const selectedPendingInvoices=customerAccounts.filter(r=>balanceOf(r)>0);
  const selectedInvoice=customerAccounts.find(r=>r.id===selectedInvoiceId);
  const customerTotal=customerAccounts.reduce((sum,r)=>sum+r.total,0),customerPaid=customerAccounts.reduce((sum,r)=>sum+r.paid,0),customerBalance=customerAccounts.reduce((sum,r)=>sum+balanceOf(r),0);
  const collect=(r:Receivable)=>{if(!canWrite||processing.current.has(r.id))return;processing.current.add(r.id);const value=Number(newPaymentAmount||0),balance=balanceOf(r),method=newPaymentMethod,reference=newPaymentReference.trim(),kind=newMovementType;if(!Number.isFinite(value)||value<=0){processing.current.delete(r.id);setNotice('Ingresa un monto mayor que cero.');return;}if(kind!=='Nota de débito'&&value>balance){processing.current.delete(r.id);setNotice('El monto no puede superar el saldo pendiente de la factura.');return;}if(kind==='Cobro'&&method==='Transferencia'&&!reference){processing.current.delete(r.id);setNotice('Ingresa la referencia de la transferencia para registrar el cobro.');return;}const date=new Date().toISOString(),movement:PaymentTransaction={id:Math.max(Date.now(),...transactions.map(t=>Number(t.id)||0))+1,type:kind,accountId:r.id,party:r.customer,amount:value,date,paymentMethod:kind==='Cobro'?method:undefined,reference,balanceBefore:balance,balanceAfter:kind==='Nota de débito'?balance+value:Math.max(0,balance-value)};setReceivables(current=>current.map(x=>x.id===r.id?kind==='Cobro'?{...x,paid:x.paid+value,lastPaymentDate:date}:kind==='Nota de crédito'?{...x,creditNotes:(x.creditNotes||0)+value}:{...x,debitNotes:(x.debitNotes||0)+value}:x));setTransactions(items=>[movement,...items]);if(kind==='Cobro'){setLastReceiptId(movement.id);printReceipt(movement);}else{printReceivableNote(movement);}setNewPaymentAmount('');setNewPaymentReference('');setSelectedInvoiceId(null);setPaymentModalOpen(false);setNewMovementType('Cobro');setNotice(kind==='Cobro'?'Abono registrado correctamente.':kind+' aplicada correctamente.');};
  return <div className="content">
    {!canWrite&&<div className="settings-notice" role="status">{syncStatus==='error'?'Solo lectura: falló la sincronización. Revisa la conexión antes de registrar operaciones.':syncStatus==='loading'?'Cargando los datos de la cuenta. Las operaciones estarán disponibles al terminar.':'Guardando cambios en la nube. Espera a que termine la sincronización.'}</div>}
    <div className="page-head"><div></div><button className="secondary" onClick={()=>window.print()}><Printer size={16}/> Imprimir</button></div>
    {notice&&<div className="settings-notice" role="status"><span>{notice}</span>{lastReceiptId!==null&&transactions.some(t=>t.id===lastReceiptId&&t.type==='Cobro')&&<button className="secondary" onClick={()=>{const payment=transactions.find(t=>t.id===lastReceiptId);if(payment)printReceipt(payment);}}><Printer size={14}/> Imprimir recibo</button>}<button onClick={()=>{setNotice('');setLastReceiptId(null);}} aria-label="Cerrar aviso">×</button></div>}
    <div className="grid metrics"><article className="card metric"><div className="metric-top"><span>Saldo pendiente</span><FileText size={20}/></div><strong>{money(pending)}</strong><small>{receivables.filter(r=>balanceOf(r)>0).length} facturas abiertas</small></article><article className="card metric"><div className="metric-top"><span>Saldo vencido</span><AlertTriangle size={20}/></div><strong>{money(lateTotal)}</strong><small>Requiere seguimiento</small></article><article className="card metric"><div className="metric-top"><span>Cuentas pagadas</span><CheckCircle2 size={20}/></div><strong>{receivables.filter(r=>balanceOf(r)===0).length}</strong><small>Facturas completadas</small></article></div>
    <section className="card receivables-customer-search"><div className="card-title"><div><h3>Buscar cliente deudor</h3></div></div><div className="receivables-search-field"><label htmlFor="receivables-search">Cliente</label><div className="receivables-search-control"><Search size={18} aria-hidden="true"/><input id="receivables-search" value={search} onChange={e=>{setSearch(e.target.value);if(selectedCustomer&&normalizeSearch(selectedCustomer)!==normalizeSearch(e.target.value))setSelectedCustomer('');}} placeholder="Escribe el nombre del cliente" autoComplete="off"/>{search&&<button type="button" className="receivables-clear" onClick={()=>{setSearch('');setSelectedCustomer('');}} aria-label="Limpiar búsqueda">×</button>}</div>{search&&!selectedCustomer&&<div className="receivables-customer-results">{customerMatches.slice(0,8).map(name=><button type="button" key={name} onClick={()=>{setSelectedCustomer(name);setSearch(name);}}><span>{name}</span><small>{receivables.filter(r=>normalizeSearch(r.customer)===normalizeSearch(name)&&balanceOf(r)>0).length} facturas pendientes</small></button>)}{customerMatches.length===0&&<p>No se encontraron clientes con cuentas registradas.</p>}</div>}</div></section>
    {selectedCustomer&&<section className="card receivables-customer-ledger"><div className="receivables-ledger-head"><div><h3>{selectedCustomer}</h3><p>Movimientos y facturas de este cliente</p></div><div className="receivables-ledger-actions"><button type="button" className="secondary" onClick={()=>printCustomerStatement(selectedCustomer)}><Printer size={15}/> Estado de cuenta</button><button type="button" className="primary" disabled={!canWrite||selectedPendingInvoices.length===0} onClick={()=>{setSelectedInvoiceId(selectedPendingInvoices[0]?.id??null);setNewPaymentAmount('');setNewPaymentReference('');setPaymentModalOpen(true);}}><Plus size={16}/> Nuevo abono</button></div></div>
      <div className="receivables-ledger-summary"><div><small>Total facturado</small><strong>{money(customerTotal)}</strong></div><div><small>Total abonado</small><strong>{money(customerPaid)}</strong></div><div><small>Saldo pendiente</small><strong>{money(customerBalance)}</strong></div><div><small>Facturas pendientes</small><strong>{selectedPendingInvoices.length}</strong></div></div>
      <div className="table-wrap"><table><thead><tr><th>Fecha</th><th>Movimiento</th><th>Documento</th><th>Descripción</th><th>Cargo</th><th>Abono</th><th>Saldo factura</th><th>Documento</th></tr></thead><tbody>{customerMovements.map(m=><tr key={m.key}><td>{day(m.date)}</td><td><span className={m.kind==='Abono'?'receivables-credit-tag':'receivables-debit-tag'}>{m.kind}</span></td><td>{m.reference}</td><td>{m.description}</td><td>{m.debit?money(m.debit):'—'}</td><td>{m.credit?money(m.credit):'—'}</td><td>{money(balanceOf(customerAccounts.find(r=>r.id===m.accountId)!))}</td><td>{m.kind==='Abono'&&<button type="button" className="secondary receivable-print-button" onClick={()=>{const p=transactions.find(t=>t.id===Number(m.key.replace('movement-','')));if(p)printReceipt(p);}}><Printer size={13}/> Recibo</button>}{(m.kind==='Nota de crédito'||m.kind==='Nota de débito')&&<button type="button" className="secondary receivable-print-button" onClick={()=>{const note=transactions.find(t=>t.id===Number(m.key.replace('movement-','')));if(note)printReceivableNote(note);}}><Printer size={13}/> Imprimir nota</button>}</td></tr>)}{customerAccounts.length===0&&<tr><td colSpan={8}>Este cliente no tiene movimientos registrados.</td></tr>}</tbody></table></div>
      <div className="receivables-invoices"><h4>Facturas del cliente</h4><div className="table-wrap"><table><thead><tr><th>Factura</th><th>Fecha</th><th>Vencimiento</th><th>Total</th><th>Abonado</th><th>Saldo</th><th>Estado</th></tr></thead><tbody>{customerAccounts.map(r=>{const b=balanceOf(r),late=overdue(r.dueDate,b);return <tr key={r.id}><td>#{r.saleId}</td><td>{day(r.date)}</td><td>{day(r.dueDate)}</td><td>{money(r.total)}</td><td>{money(r.paid)}</td><td><strong>{money(b)}</strong></td><td><span className="pill">{b===0?'Pagada':late?'Vencida':'Pendiente'}</span></td></tr>;})}</tbody></table></div></div>
    </section>}
    {!selectedCustomer&&<div className="card receivables-empty-ledger"><FileText size={24}/><strong>Busca y selecciona un cliente</strong><span>Al seleccionarlo aparecerán todas sus facturas, abonos y saldos.</span></div>}
    {paymentModalOpen&&<div className="modal-backdrop receivables-modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setPaymentModalOpen(false);}}><section className="modal receivables-payment-modal" role="dialog" aria-modal="true" aria-labelledby="receivables-payment-title"><div className="modal-head"><div><h2 id="receivables-payment-title">Nuevo abono</h2><p>Cliente: {selectedCustomer}</p></div><button type="button" className="icon-btn" onClick={()=>setPaymentModalOpen(false)} aria-label="Cerrar">×</button></div><div className="receivables-modal-invoices"><h4>Selecciona la factura pendiente</h4>{selectedPendingInvoices.map(r=><label className={'receivables-invoice-option'+(selectedInvoiceId===r.id?' selected':'')} key={r.id}><input type="radio" name="receivables-invoice" checked={selectedInvoiceId===r.id} onChange={()=>{setSelectedInvoiceId(r.id);setNewPaymentAmount('');}}/><span><strong>Factura #{r.saleId}</strong><small>Fecha: {day(r.date)} · Vence: {day(r.dueDate)}</small></span><span><strong>{money(balanceOf(r))}</strong><small>Saldo pendiente</small></span></label>)}</div>{selectedInvoice&&<div className="receivables-payment-fields"><div className="receivables-selected-balance"><span>Saldo actual de la factura</span><strong>{money(balanceOf(selectedInvoice))}</strong></div><label>Tipo de movimiento<select value={newMovementType} onChange={e=>{setNewMovementType(e.target.value as 'Cobro'|'Nota de crédito'|'Nota de débito');setNewPaymentAmount('');setNewPaymentReference('');}}><option value="Cobro">Abono (efectivo o transferencia)</option><option value="Nota de crédito">Aplicar nota de crédito</option><option value="Nota de débito">Aplicar nota de débito</option></select></label><label>{newMovementType==='Cobro'?'Monto del abono':newMovementType==='Nota de crédito'?'Monto de la nota de crédito':'Monto de la nota de débito'}<input type="number" min="0.01" max={newMovementType==='Nota de débito'?undefined:balanceOf(selectedInvoice)} step="0.01" value={newPaymentAmount} onChange={e=>setNewPaymentAmount(e.target.value)} placeholder="0.00"/></label>{newMovementType==='Cobro'&&<label>Medio de pago<select value={newPaymentMethod} onChange={e=>setNewPaymentMethod(e.target.value as 'Efectivo'|'Transferencia')}><option value="Efectivo">Efectivo</option><option value="Transferencia">Transferencia</option></select></label>}<label>{newMovementType==='Cobro'?'Referencia (opcional)':'Número de documento / referencia'}<input value={newPaymentReference} onChange={e=>setNewPaymentReference(e.target.value)} placeholder={newMovementType==='Cobro'?'Referencia del pago':'Número de nota o documento'}/></label></div>}<div className="modal-actions"><button type="button" className="secondary" onClick={()=>setPaymentModalOpen(false)}>Cancelar</button><button type="button" className="primary" disabled={!canWrite||!selectedInvoice||!Number.isFinite(Number(newPaymentAmount))||Number(newPaymentAmount)<=0||(newMovementType!=='Nota de débito'&&Number(newPaymentAmount)>balanceOf(selectedInvoice))||(newMovementType==='Cobro'&&newPaymentMethod==='Transferencia'&&!newPaymentReference.trim())} onClick={()=>selectedInvoice&&collect(selectedInvoice)}>{newMovementType==='Cobro'?'Registrar e imprimir recibo':newMovementType==='Nota de crédito'?'Registrar e imprimir nota de crédito':'Registrar e imprimir nota de débito'}</button></div></section></div>}
    <section className="card receivables-history-card"><button type="button" className="receivables-history-toggle" aria-expanded={historyOpen} aria-controls="receivables-payment-history" onClick={()=>setHistoryOpen(open=>!open)}><span className="receivables-history-title"><strong>Historial de cobros</strong><small>{paymentHistory.length} {paymentHistory.length===1?'abono registrado':'abonos registrados'}</small></span><ChevronDown size={19} className={historyOpen?'is-open':''}/></button>{historyOpen&&<div className="table-wrap" id="receivables-payment-history"><table><thead><tr><th>Fecha y hora</th><th>Cliente</th><th>Cuenta / venta</th><th>Medio de pago</th><th>Referencia</th><th>Importe recibido</th><th>Recibo</th></tr></thead><tbody>{paymentHistory.map(t=><tr key={t.id}><td>{day(t.date)}</td><td>{t.party}</td><td>#{receivables.find(r=>r.id===t.accountId)?.saleId??t.accountId}</td><td>{t.paymentMethod||'—'}</td><td>{t.reference||'—'}</td><td>{money(t.amount)}</td><td><button type="button" className="secondary receivable-print-button" onClick={()=>printReceipt(t)}><Printer size={14}/> Imprimir</button></td></tr>)}{paymentHistory.length===0&&<tr><td colSpan={7}>Todavía no hay cobros registrados.</td></tr>}</tbody></table></div>}</section>
  </div>;
}

export function PayablesModule({payables,setPayables,transactions,setTransactions,remoteReady,syncStatus}:{payables:Payable[];setPayables:Dispatch<SetStateAction<Payable[]>>;transactions:PaymentTransaction[];setTransactions:Dispatch<SetStateAction<PaymentTransaction[]>>;remoteReady:boolean;syncStatus:'loading'|'saving'|'synced'|'error'}) {
  const canWrite=canWriteFinance(remoteReady,syncStatus);
  const [search,setSearch]=useState(''); const [status,setStatus]=useState('pendiente'); const [amounts,setAmounts]=useState<Record<number,string>>({}); const [methods,setMethods]=useState<Record<number,'Efectivo'|'Transferencia'>>({}); const [notice,setNotice]=useState(''); const processing=useRef<Set<number>>(new Set()); useEffect(()=>{processing.current.clear();},[payables,transactions]);
  const filtered=useMemo(()=>payables.filter(r=>{const b=balanceOf(r),late=overdue(r.dueDate,b);const s=status==='todos'||(status==='pendiente'&&b>0)||(status==='vencida'&&late)||(status==='pagada'&&b===0);return s&&`${r.supplier}`.toLowerCase().includes(search.toLowerCase());}),[payables,search,status]);
  const pending=payables.reduce((s,r)=>s+balanceOf(r),0),lateTotal=payables.reduce((s,r)=>s+(overdue(r.dueDate,balanceOf(r))?balanceOf(r):0),0);
  const pay=(r:Payable)=>{if(!canWrite||processing.current.has(r.id))return;processing.current.add(r.id);const value=Number(amounts[r.id]||0),balance=balanceOf(r);if(!validAmount(value,balance)){processing.current.delete(r.id);setNotice('Ingresa un pago mayor que cero y no superior al saldo pendiente.');return;}const date=new Date().toISOString();setPayables(current=>current.map(x=>x.id===r.id?{...x,paid:Math.min(x.total,x.paid+value),lastPaymentDate:date}:x));setTransactions(items=>[{id:Math.max(Date.now(),...items.map(t=>Number(t.id)||0))+1,type:'Pago proveedor',accountId:r.id,party:r.supplier,amount:value,date,paymentMethod:methods[r.id]||'Efectivo'},...items]);setAmounts(currentAmounts=>({...currentAmounts,[r.id]:''}));setNotice('Pago registrado correctamente.');};
  return <div className="content">
    {!canWrite&&<div className="settings-notice" role="status">{syncStatus==='error'?'Solo lectura: falló la sincronización. Revisa la conexión antes de registrar operaciones.':syncStatus==='loading'?'Cargando los datos de la cuenta. Las operaciones estarán disponibles al terminar.':'Guardando cambios en la nube. Espera a que termine la sincronización.'}</div>}
    <div className="page-head"><div><span className="pill">GESTIÓN FINANCIERA</span><h2>Cuentas por pagar</h2><p>Obligaciones con proveedores, pagos parciales y fechas de vencimiento.</p></div><button className="secondary" onClick={()=>window.print()}><Printer size={16}/> Imprimir</button></div>
    {notice&&<div className="settings-notice" role="status">{notice}<button onClick={()=>setNotice('')} aria-label="Cerrar aviso">×</button></div>}
    <div className="grid metrics"><article className="card metric"><div className="metric-top"><span>Saldo pendiente</span><FileText size={20}/></div><strong>{money(pending)}</strong><small>{payables.filter(r=>balanceOf(r)>0).length} obligaciones abiertas</small></article><article className="card metric"><div className="metric-top"><span>Saldo vencido</span><AlertTriangle size={20}/></div><strong>{money(lateTotal)}</strong><small>Requiere seguimiento</small></article><article className="card metric"><div className="metric-top"><span>Obligaciones pagadas</span><CheckCircle2 size={20}/></div><strong>{payables.filter(r=>balanceOf(r)===0).length}</strong><small>Completadas</small></article></div>
    <section className="card"><div className="card-title"><div><h3>Registro de obligaciones</h3><p>Las compras a crédito se incorporan desde Compras.</p></div></div><div className="toolbar"><label className="search-box"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar proveedor"/></label><select value={status} onChange={e=>setStatus(e.target.value)}><option value="pendiente">Pendientes</option><option value="vencida">Vencidas</option><option value="pagada">Pagadas</option><option value="todos">Todas</option></select></div>
    <div className="table-wrap"><table><thead><tr><th>Proveedor</th><th>Fecha</th><th>Vencimiento</th><th>Total</th><th>Abonado</th><th>Saldo</th><th>Estado / pago</th></tr></thead><tbody>{filtered.map(r=>{const b=balanceOf(r),late=overdue(r.dueDate,b);return <tr key={r.id}><td>{r.supplier||'Proveedor no especificado'}</td><td>{day(r.date)}</td><td>{day(r.dueDate)}</td><td>{money(r.total)}</td><td>{money(r.paid)}</td><td><strong>{money(b)}</strong></td><td>{b===0?<span className="pill">Pagada</span>:<><span className="pill">{late?'Vencida':'Pendiente'}</span><div className="account-payment"><input type="number" min="0.01" max={b} step="0.01" value={amounts[r.id]??''} onChange={e=>setAmounts({...amounts,[r.id]:e.target.value})} placeholder="Pago"/><select value={methods[r.id]||'Efectivo'} onChange={e=>setMethods({...methods,[r.id]:e.target.value as 'Efectivo'|'Transferencia'})}><option>Efectivo</option><option>Transferencia</option></select><button className="primary" disabled={!canWrite} onClick={()=>pay(r)}><Plus size={14}/> Pagar</button></div></>}</td></tr>;})}{filtered.length===0&&<tr><td colSpan={7}>No hay obligaciones que coincidan con los filtros.</td></tr>}</tbody></table></div></section>
    <section className="card"><div className="card-title"><div><h3>Historial de pagos</h3><p>Pagos registrados a proveedores.</p></div></div><div className="table-wrap"><table><thead><tr><th>Fecha</th><th>Proveedor</th><th>Cuenta</th><th>Método</th><th>Importe</th></tr></thead><tbody>{transactions.filter(t=>t.type==='Pago proveedor').map(t=><tr key={t.id}><td>{day(t.date)}</td><td>{t.party}</td><td>#{t.accountId}</td><td>{t.paymentMethod||'—'}</td><td>{money(t.amount)}</td></tr>)}{transactions.filter(t=>t.type==='Pago proveedor').length===0&&<tr><td colSpan={5}>Todavía no hay pagos registrados.</td></tr>}</tbody></table></div></section>
  </div>;
}

type ReportProps={sales:SaleRecord[];purchases:PurchaseRecord[];expenses:Expense[];receivables:Receivable[];payables:Payable[];closures:CashClosure[];transactions:PaymentTransaction[];settings:ErpSettings;products:Product[];inventoryMovements:InventoryMovement[];cashMovements:CashMovement[];customers:Customer[];suppliers:Supplier[];missingProductRequests:MissingProductRequest[];setMissingProductRequests:Dispatch<SetStateAction<MissingProductRequest[]>>};
export function ReportsModule({sales,purchases,expenses,receivables,payables,closures,transactions,settings,products,inventoryMovements,cashMovements,customers,suppliers,missingProductRequests,setMissingProductRequests}:ReportProps) {
  const [kind,setKind]=useState('resumen');const [from,setFrom]=useState('');const [to,setTo]=useState('');const [query,setQuery]=useState('');const [includeCatalogPrice,setIncludeCatalogPrice]=useState(false);
  const inRange=(date:string)=>{const d=date.slice(0,10);return (!from||d>=from)&&(!to||d<=to);};
  const ar=receivables.filter(x=>balanceOf(x)>0&&inRange(x.date)&&x.customer.toLowerCase().includes(query.toLowerCase()));
  const ap=payables.filter(x=>balanceOf(x)>0&&inRange(x.date)&&x.supplier.toLowerCase().includes(query.toLowerCase()));
  const selectedTx=transactions.filter(x=>inRange(x.date)&&x.party.toLowerCase().includes(query.toLowerCase()));
  const totalSales=sales.filter(x=>inRange(x.date)).reduce((s,x)=>s+x.total,0),totalExpenses=expenses.filter(x=>inRange(x.date)).reduce((s,x)=>s+x.amount,0);
  const totalPurchases=purchases.filter(x=>inRange(x.date)).reduce((s,x)=>s+x.total,0);
  const catalogProducts=products.filter(x=>`${x.name} ${x.category} ${x.laboratory} ${x.presentation} ${(x.activeIngredients||[]).join(' ')}`.toLowerCase().includes(query.toLowerCase()));
  const demandRows=useMemo(()=>{const groups=new Map<string,{name:string;presentation:string;requests:number;quantity:number;last:string;pending:number}>();missingProductRequests.filter(x=>inRange(x.requestedAt)&&`${x.name} ${x.presentation} ${x.notes}`.toLowerCase().includes(query.toLowerCase())).forEach(x=>{const key=`${x.name.trim().toLocaleLowerCase()}|${x.presentation.trim().toLocaleLowerCase()}`;const row=groups.get(key)??{name:x.name,presentation:x.presentation,requests:0,quantity:0,last:x.requestedAt,pending:0};row.requests+=1;row.quantity+=x.quantity;if(x.requestedAt>row.last)row.last=x.requestedAt;if(x.status==='Pendiente')row.pending+=1;groups.set(key,row);});return [...groups.values()].sort((a,b)=>b.requests-a.requests||b.quantity-a.quantity);},[missingProductRequests,from,to,query]);
  const printTitle=({demanda:'Demanda de productos no disponibles',catalogo:'Catálogo de productos',resumen:'Resumen financiero',cobrar:'Cuentas por cobrar',pagar:'Cuentas por pagar',cobros:'Historial de cobros y pagos',ventas:'Ventas',compras:'Compras',gastos:'Gastos',cierres:'Cierres de caja',inventario:'Inventario actual',movimientos:'Movimientos de inventario',caja:'Movimientos de caja',clientes:'Directorio de clientes',proveedores:'Directorio de proveedores'} as Record<string,string>)[kind]||'Reporte';
  const headers:Record<string,string[]> = {
    catalogo:includeCatalogPrice?['Producto','Descripción','Precio minorista','Precio mayorista']:['Producto','Descripción'],resumen:['Indicador','Importe'],cobrar:['Cliente','Venta','Fecha','Vencimiento','Total','Abonado','Saldo','Estado'],pagar:['Proveedor','Fecha','Vencimiento','Total','Abonado','Saldo','Estado'],cobros:['Fecha','Tipo','Cliente/proveedor','Método','Importe'],ventas:['Fecha','Cliente','Tipo','Método','Total'],compras:['Fecha','Proveedor','Método','Total'],gastos:['Fecha','Descripción','Categoría','Importe'],cierres:['Fecha','Apertura','Efectivo esperado','Contado','Diferencia','Nota'],inventario:['Código','Producto','Categoría','Laboratorio','Lote','Vencimiento','Existencia','Mínimo','Costo','Precio minorista','Precio mayorista','Valor al costo'],movimientos:['Fecha','Producto','Movimiento','Cantidad','Existencia anterior','Existencia nueva','Costo unitario','Referencia','Nota'],caja:['Fecha','Tipo','Descripción','Categoría','Importe'],clientes:['Cliente','Teléfono','Límite de crédito','Estado','Notas'],proveedores:['Proveedor','Contacto','Teléfono','Correo','RTN','Dirección','Condiciones','Estado'],demanda:['Producto solicitado','Presentación','Veces solicitado','Unidades solicitadas','Última solicitud','Solicitudes pendientes']
  };
  const rows:Record<string,string[][]> = {
    catalogo:catalogProducts.map(x=>includeCatalogPrice?[x.name,[x.presentation,x.category,x.laboratory,(x.activeIngredients||[]).join(', ')].filter(Boolean).join(' · '),String(x.retail),String(x.wholesale)]:[x.name,[x.presentation,x.category,x.laboratory,(x.activeIngredients||[]).join(', ')].filter(Boolean).join(' · ')]),
    resumen:[['Ventas',String(totalSales)],['Compras',String(totalPurchases)],['Gastos',String(totalExpenses)],['Por cobrar',String(ar.reduce((sum,x)=>sum+balanceOf(x),0))],['Por pagar',String(ap.reduce((sum,x)=>sum+balanceOf(x),0))]],
    cobrar:ar.map(x=>[x.customer,String(x.saleId),day(x.date),day(x.dueDate),String(x.total),String(x.paid),String(balanceOf(x)),overdue(x.dueDate,balanceOf(x))?'Vencida':'Pendiente']),
    pagar:ap.map(x=>[x.supplier,day(x.date),day(x.dueDate),String(x.total),String(x.paid),String(balanceOf(x)),overdue(x.dueDate,balanceOf(x))?'Vencida':'Pendiente']),
    cobros:selectedTx.map(x=>[day(x.date),x.type,x.party,x.paymentMethod||'—',String(x.amount)]),
    ventas:sales.filter(x=>inRange(x.date)&&String(x.customer||'').toLowerCase().includes(query.toLowerCase())).map(x=>[day(x.date),x.customer||'Venta general',x.type,x.payment,String(x.total)]),
    compras:purchases.filter(x=>inRange(x.date)&&x.supplier.toLowerCase().includes(query.toLowerCase())).map(x=>[day(x.date),x.supplier,x.paymentMethod,String(x.total)]),
    gastos:expenses.filter(x=>inRange(x.date)&&x.description.toLowerCase().includes(query.toLowerCase())).map(x=>[day(x.date),x.description,x.category,String(x.amount)]),
    cierres:closures.filter(x=>inRange(x.date)).map(x=>[day(x.date),String(x.opening),String(x.expected),String(x.counted),String(x.difference),x.note||'—']),
    inventario:products.filter(x=>`${x.name} ${x.code} ${x.category} ${x.lot}`.toLowerCase().includes(query.toLowerCase())).map(x=>[x.code,x.name,x.category,x.laboratory,x.lot,day(x.expiry),String(x.stock),String(x.minStock),String(x.cost),String(x.retail),String(x.wholesale),String(x.stock*x.cost)]),
    movimientos:inventoryMovements.filter(x=>inRange(x.date)&&`${x.productName} ${x.type} ${x.note||''}`.toLowerCase().includes(query.toLowerCase())).map(x=>[day(x.date),x.productName,x.type,String(x.quantity),String(x.stockBefore),String(x.stockAfter),String(x.unitCost),String(x.referenceId??''),x.note||'—']),
    caja:cashMovements.filter(x=>inRange(x.date)&&`${x.description} ${x.category} ${x.type}`.toLowerCase().includes(query.toLowerCase())).map(x=>[day(x.date),x.type,x.description,x.category,String(x.amount)]),
    clientes:customers.filter(x=>`${x.name} ${x.phone}`.toLowerCase().includes(query.toLowerCase())).map(x=>[x.name,x.phone,String(x.creditLimit),x.active?'Activo':'Inactivo',x.notes||'—']),
    proveedores:suppliers.filter(x=>`${x.name} ${x.contact} ${x.phone}`.toLowerCase().includes(query.toLowerCase())).map(x=>[x.name,x.contact,x.phone,x.email,x.rtn,x.address,x.paymentTerms,x.active?'Activo':'Inactivo']),
    demanda:demandRows.map(x=>[x.name,x.presentation||'—',String(x.requests),String(x.quantity),day(x.last),String(x.pending)])
  };
  const exportCatalog=()=>{
    const cards=catalogProducts.map(p=>{
      const description=[p.presentation,p.category,p.laboratory,(p.activeIngredients||[]).join(', ')].filter(Boolean).join(' · ');
      const photo=p.imageUrl?'<img src="'+escapeHtml(p.imageUrl)+'" alt="'+escapeHtml(p.name)+'">':'<span>Sin imagen</span>';
      const price=includeCatalogPrice?'<div class="price">Minorista: '+escapeHtml(money(p.retail))+' · Mayorista: '+escapeHtml(money(p.wholesale))+'</div>':'';
      return '<article class="product"><div class="photo">'+photo+'</div><h2>'+escapeHtml(p.name)+'</h2><p>'+escapeHtml(description||'Sin descripción adicional')+'</p>'+price+'</article>';
    }).join('');
    const html='<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catálogo de productos - DIFARMÁS</title><style>body{font-family:Arial,sans-serif;color:#243044;margin:24px}header{text-align:center;border-bottom:2px solid #167c70;margin-bottom:22px;padding-bottom:12px}header h1{margin:0;color:#167c70}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.product{border:1px solid #dce3e8;border-radius:10px;padding:12px;break-inside:avoid}.photo{height:170px;display:flex;align-items:center;justify-content:center;background:#fff}.photo img{max-width:100%;max-height:165px;object-fit:contain}.product h2{font-size:16px;margin:10px 0 6px}.product p{font-size:13px;line-height:1.45;margin:0}.price{font-weight:bold;margin-top:10px;color:#167c70}@media(max-width:700px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media print{body{margin:10mm}.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.product{break-inside:avoid}}</style></head><body><header><h1>'+escapeHtml(settings.businessName||'DIFARMÁS')+'</h1><p>Catálogo de productos · '+catalogProducts.length+' productos</p></header><main class="grid">'+cards+'</main></body></html>';
    const blob=new Blob([html],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='DIFARMAS_catalogo_'+new Date().toISOString().slice(0,10)+'.html';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);
  };
  const exportExcel=()=>{const head=headers[kind]||[];const data=rows[kind]||[];const csv=[head,...data].map(row=>row.map(value=>{const v=String(value??'');return '"'+v.replace(/"/g,'""')+'"';}).join(';')).join('\r\n');const blob=new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`DIFARMAS_${kind}_${new Date().toISOString().slice(0,10)}.csv`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);};
  return <div className="content">
    <div className="page-head"><div><span className="pill">REPORTES</span><h2>Impresión de reportes</h2><p>Filtra la información, revisa el resumen e imprime o guarda como PDF desde el diálogo del navegador.</p></div><div className="report-actions no-print">{kind==='catalogo'&&<button className="secondary" onClick={exportCatalog}><FileText size={16}/> Descargar catálogo</button>}<button className="secondary" onClick={exportExcel}><FileSpreadsheet size={16}/> Exportar a Excel (CSV)</button><button className="primary" onClick={()=>window.print()}><Printer size={16}/> Imprimir / Guardar PDF</button></div></div>
    <section className="card no-print"><div className="settings-form-grid"><label>Tipo de reporte<select value={kind} onChange={e=>setKind(e.target.value)}><option value="catalogo">Catálogo de productos</option><option value="resumen">Resumen financiero</option><option value="cobrar">Cuentas por cobrar</option><option value="pagar">Cuentas por pagar</option><option value="cobros">Historial de cobros y pagos</option><option value="ventas">Ventas</option><option value="compras">Compras</option><option value="gastos">Gastos</option><option value="cierres">Cierres de caja</option><option value="inventario">Inventario actual</option><option value="movimientos">Movimientos de inventario</option><option value="caja">Movimientos de caja</option><option value="clientes">Directorio de clientes</option><option value="proveedores">Directorio de proveedores</option><option value="demanda">Productos más solicitados (sin existencia)</option></select></label><label>Desde<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>Hasta<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><label>{kind==='catalogo'?'Buscar producto':'Buscar cliente/proveedor'}<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Nombre (opcional)"/></label>{kind==='catalogo'&&<label className="checkbox-label"><input type="checkbox" checked={includeCatalogPrice} onChange={e=>setIncludeCatalogPrice(e.target.checked)}/> Incluir precios (opcional)</label>}</div></section>
    <section className="card report-print"><div className="card-title"><div><h3>{settings.businessName||'DIFARMÁS'} · {printTitle}</h3><p>Generado el {new Date().toLocaleString('es-HN')} · Moneda: HNL</p><p>Periodo: {from||'Inicio'} a {to||'Hoy'}{query?' · Filtro: '+query:''}</p></div></div>
    {kind==='catalogo'&&<div className="catalog-print-grid">{catalogProducts.map(p=><article className="catalog-product" key={p.id}><div className="catalog-product-image">{p.imageUrl?<img src={p.imageUrl} alt={p.name} onError={e=>{e.currentTarget.style.display='none';}}/>:<span>Sin imagen</span>}</div><h4>{p.name}</h4><p>{[p.presentation,p.category,p.laboratory,(p.activeIngredients||[]).join(', ')].filter(Boolean).join(' · ')||'Sin descripción adicional'}</p>{includeCatalogPrice&&<strong>Minorista: {money(p.retail)} · Mayorista: {money(p.wholesale)}</strong>}</article>)}{catalogProducts.length===0&&<p>No hay productos para el filtro seleccionado.</p>}</div>}
    {kind==='resumen'&&<><div className="grid metrics"><article className="card metric"><span>Ventas</span><strong>{money(totalSales)}</strong></article><article className="card metric"><span>Compras</span><strong>{money(totalPurchases)}</strong></article><article className="card metric"><span>Gastos</span><strong>{money(totalExpenses)}</strong></article><article className="card metric"><span>Por cobrar</span><strong>{money(ar.reduce((s,x)=>s+balanceOf(x),0))}</strong></article><article className="card metric"><span>Por pagar</span><strong>{money(ap.reduce((s,x)=>s+balanceOf(x),0))}</strong></article></div></>}
    {kind==='cobrar'&&<ReportTable headers={['Cliente','Venta','Fecha','Vencimiento','Total','Abonado','Saldo','Estado']} rows={ar.map(x=>[x.customer,String(x.saleId),day(x.date),day(x.dueDate),money(x.total),money(x.paid),money(balanceOf(x)),overdue(x.dueDate,balanceOf(x))?'Vencida':'Pendiente'])}/>}
    {kind==='pagar'&&<ReportTable headers={['Proveedor','Fecha','Vencimiento','Total','Abonado','Saldo','Estado']} rows={ap.map(x=>[x.supplier,day(x.date),day(x.dueDate),money(x.total),money(x.paid),money(balanceOf(x)),overdue(x.dueDate,balanceOf(x))?'Vencida':'Pendiente'])}/>}
    {kind==='cobros'&&<ReportTable headers={['Fecha','Tipo','Cliente/proveedor','Método','Importe']} rows={selectedTx.map(x=>[day(x.date),x.type,x.party,x.paymentMethod||'—',money(x.amount)])}/>}
    {kind==='ventas'&&<ReportTable headers={['Fecha','Cliente','Tipo','Método','Total']} rows={sales.filter(x=>inRange(x.date)&&String(x.customer||'').toLowerCase().includes(query.toLowerCase())).map(x=>[day(x.date),x.customer||'Venta general',x.type,x.payment,money(x.total)])}/>}
    {kind==='compras'&&<ReportTable headers={['Fecha','Proveedor','Método','Total']} rows={purchases.filter(x=>inRange(x.date)&&x.supplier.toLowerCase().includes(query.toLowerCase())).map(x=>[day(x.date),x.supplier,x.paymentMethod,money(x.total)])}/>}
    {kind==='gastos'&&<ReportTable headers={['Fecha','Descripción','Categoría','Importe']} rows={expenses.filter(x=>inRange(x.date)&&x.description.toLowerCase().includes(query.toLowerCase())).map(x=>[day(x.date),x.description,x.category,money(x.amount)])}/>}
    {kind==='cierres'&&<ReportTable headers={headers.cierres} rows={rows.cierres.map(r=>[r[0],money(Number(r[1])),money(Number(r[2])),money(Number(r[3])),money(Number(r[4])),r[5]])}/>}
    {kind==='inventario'&&<ReportTable headers={headers.inventario} rows={rows.inventario.map(r=>[...r.slice(0,8),money(Number(r[8])),money(Number(r[9])),money(Number(r[10])),money(Number(r[11]))])}/>}
    {kind==='movimientos'&&<ReportTable headers={headers.movimientos} rows={rows.movimientos.map(r=>[...r.slice(0,6),money(Number(r[6])),r[7],r[8]])}/>}
    {kind==='caja'&&<ReportTable headers={headers.caja} rows={rows.caja.map(r=>[...r.slice(0,4),money(Number(r[4]))])}/>}
    {kind==='clientes'&&<ReportTable headers={headers.clientes} rows={rows.clientes}/>}
    {kind==='proveedores'&&<ReportTable headers={headers.proveedores} rows={rows.proveedores}/>}
    {kind==='demanda'&&<><div className="grid metrics"><article className="card metric"><span>Productos diferentes</span><strong>{demandRows.length}</strong></article><article className="card metric"><span>Solicitudes registradas</span><strong>{demandRows.reduce((s,x)=>s+x.requests,0)}</strong></article><article className="card metric"><span>Unidades solicitadas</span><strong>{demandRows.reduce((s,x)=>s+x.quantity,0)}</strong></article></div><ReportTable headers={headers.demanda} rows={rows.demanda}/><div className="card-title" style={{marginTop:'20px'}}><div><h3>Solicitudes y seguimiento de compras</h3><p>Marca cada solicitud como pendiente, comprado o descartado.</p></div></div><div className="table-wrap"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Presentación</th><th>Cantidad</th><th>Nota</th><th>Estado</th></tr></thead><tbody>{missingProductRequests.filter(x=>inRange(x.requestedAt)&&`${x.name} ${x.presentation} ${x.notes}`.toLowerCase().includes(query.toLowerCase())).map(x=><tr key={x.id}><td>{day(x.requestedAt)}</td><td>{x.name}</td><td>{x.presentation||'—'}</td><td>{x.quantity}</td><td>{x.notes||'—'}</td><td><select aria-label={'Estado de '+x.name} value={x.status} onChange={e=>setMissingProductRequests(current=>current.map(item=>item.id===x.id?{...item,status:e.target.value as MissingProductRequest['status']}:item))}><option value="Pendiente">Pendiente de compra</option><option value="Comprado">Comprado</option><option value="Descartado">Descartado</option></select></td></tr>)}{missingProductRequests.filter(x=>inRange(x.requestedAt)&&`${x.name} ${x.presentation} ${x.notes}`.toLowerCase().includes(query.toLowerCase())).length===0&&<tr><td colSpan={6}>Aún no hay solicitudes registradas para este período.</td></tr>}</tbody></table></div></>}

    <div className="report-footnote">Documento de uso interno · DIFARMÁS ERP</div></section>
  </div>;
}
function ReportTable({headers,rows}:{headers:string[];rows:string[][]}) {return <div className="table-wrap"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{cell}</td>)}</tr>)}{rows.length===0&&<tr><td colSpan={headers.length}>No hay registros para los filtros seleccionados.</td></tr>}</tbody></table></div>;}
